previewCss:
.darma-loader-sailboat-bob {
  position: relative;
  width: 48px;
  height: 48px;
}
.darma-loader-sailboat-bob::after {
  content: "";
  position: absolute;
  bottom: 6px;
  left: 0;
  right: 0;
  height: 3px;
  border-radius: 2px;
  background: #c7d2fe;
}
.darma-loader-sailboat-bob i {
  position: absolute;
  bottom: 9px;
  left: 50%;
  width: 30px;
  height: 10px;
  margin-left: -15px;
  background: var(--loader-color, #6366f1);
  clip-path: polygon(6% 0, 94% 0, 78% 100%, 22% 100%);
  transform-origin: bottom center;
  animation: darma-loader-sailboat-bob-rock 1.8s ease-in-out infinite;
}
.darma-loader-sailboat-bob i::before {
  content: "";
  position: absolute;
  bottom: 8px;
  left: 50%;
  width: 16px;
  height: 22px;
  margin-left: -6px;
  background: var(--loader-color, #6366f1);
  clip-path: polygon(0 0, 0 100%, 100% 100%);
}
@keyframes darma-loader-sailboat-bob-rock {
  0%, 100% { transform: rotate(-8deg); }
  50% { transform: rotate(8deg); }
}

